INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5209, '卡利姆多的博学者') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5805, '欢迎来到魔兽世界!$B$B为了感谢您购买魔兽世界典藏版，请将这张礼券交给北郡山谷的梅里萨·斯蒂维尔。您将得到一份特别的礼物：陪伴您踏上冒险旅途的小宠物!$B$B再次感谢您的支持，请尽情享受魔兽世界的乐趣吧!') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5841, '欢迎来到魔兽世界！$B$B请把礼品票给寒脊山谷的尤里·碎盔，你将会得到一份礼品：一个小战友他将会陪伴你的富有冒险与光荣的征程。$B$B再次感谢，希望您在魔兽世界里获得快乐！') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5842, '欢迎来到魔兽世界！$B$B请把礼品票给幽影谷的奥雷希尔•语风，你将会得到一份礼品：一个小战友他将会陪伴你的富有冒险与光荣的征程。$B$B再次感谢，希望您在魔兽世界里获得快乐！') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5843, '欢迎来到魔兽世界！$B$B请把礼品票给试炼谷的玛卡尔，你将会得到一份礼品：一个小战友他将会陪伴你的富有冒险与光荣的征程。$B$B再次感谢，希望您在魔兽世界里获得快乐！') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5844, '欢迎来到魔兽世界！$B$B请把礼品票给纳拉其营地的沃恩·星眼，你将会得到一份礼品：一个小战友他将会陪伴你的富有冒险与光荣的征程。$B$B再次感谢，希望您在魔兽世界里获得快乐！') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (5847, '欢迎来到魔兽世界！$B$B请把礼品票给丧钟镇的克莱尔·韦洛，你将会得到一份礼品：一个小战友他将会陪伴你的富有冒险与光荣的征程。$B$B再次感谢，希望您在魔兽世界里获得快乐！') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (7221, '啊，魔兽资料库网友，你是来向我报到的?太好了，雷矛部族需要各方面的支援!$B和丹巴达尔的勘察员塔雷·石镐谈谈吧，你可以在丹巴达尔兵营的最下层找到他。$B当你穿越丹巴达尔的时候多四处看看。对于一个勤劳的魔兽资料库网友来说，根本不用担心找不到事情做。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (7222, '一个魔兽资料库网友?太好了!我们很高兴在奥特兰克看到你，魔兽资料库网友。无耻的矮人和他们的盟军入侵了我们的山谷，我们欢迎所有部落的成员加入这场正义的战斗!$B去和沃加·死爪谈谈吧。他正在寻找足够的人手来完成一项重要的任务，目标就是联盟设立在奥特兰克的城堡!$B你可以在霜狼要塞里找到沃加。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (7677, '如果你把你的白马给我带来，那么我可以让你从新的马中选择一匹。$B$B它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (7704, '啧啧……这难道不是个惊喜吗？这实在就是个惊喜啊。比拉凯琳的巨大而精美的枕头现在是你的囊中之物啦。艾沃奈斯肯定很想将她那脏兮兮的小手放在枕头上。把枕头交给她，看看她是否会奖励你点什么。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8565, '啊，对!我们当然不会忘记你过去在阿拉希盆地的成就，$N。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8566, '啊，对!我们当然不会忘记你过去在阿拉希盆地的成就，$N。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8567, '啊，对!我们当然不会忘记你过去在战歌峡谷的成就，$N。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8568, '啊，对!我们当然不会忘记你过去在战歌峡谷的成就，$N。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
