INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8856, '随着新兵增援塞纳里奥城堡，如何让他们在沙漠中生存成了一个问题。缺水是基本的问题，沙漠中无数具毒的生物对没有经验的志愿兵而言是很大的威胁。收集沙漠生存工具包需要的物资并带给塞纳里奥城堡的卡兰德拉斯。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `details_loc4`) VALUES (8869, '到斯坦索姆去杀死红衣铸锤师。将红衣铸锤师的围裙交给莉莉丝。') ON DUPLICATE KEY UPDATE `details_loc4` = VALUES(`details_loc4`);
INSERT INTO `locales_quest` (`entry`, `objectives_loc4`) VALUES (5209, '在卡利姆多完成685项任务') ON DUPLICATE KEY UPDATE `objectives_loc4` = VALUES(`objectives_loc4`);
