INSERT INTO `locales_quest` (`entry`, `objectives_loc4`) VALUES (5841, '带上寒脊山谷礼品票给尤里·碎盔。') ON DUPLICATE KEY UPDATE `objectives_loc4` = VALUES(`objectives_loc4`);
