INSERT INTO `locales_quest` (`entry`, `objectives_loc4`) VALUES (5844, '带上纳拉其营地礼物票给沃恩·星眼。') ON DUPLICATE KEY UPDATE `objectives_loc4` = VALUES(`objectives_loc4`);
