INSERT INTO `locales_quest` (`entry`, `objectives_loc4`) VALUES (7677, '如果你把你的白马给我带来，那么我可以让你从新的马中选择一匹。$B$B它们和你原来的马拥有同样的速度，但是其外观将会有所不同。看看这里的马就知道它们大概是什么样子了。') ON DUPLICATE KEY UPDATE `objectives_loc4` = VALUES(`objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `objectives_loc4`) VALUES (7704, '将比拉凯琳的枕头带给灼热峡谷的艾沃奈斯。') ON DUPLICATE KEY UPDATE `objectives_loc4` = VALUES(`objectives_loc4`);
