INSERT INTO `locales_quest` (`entry`, `offerrewardtext_loc4`) VALUES (7704, '啧啧……这难道不是个惊喜吗？这实在就是个惊喜啊。比拉凯琳的巨大而精美的枕头现在是你的囊中之物啦。$B$B艾沃奈斯肯定很想将她那脏兮兮的小手放在枕头上。把枕头交给她，看看她是否会奖励你点什么。$N！') ON DUPLICATE KEY UPDATE `offerrewardtext_loc4` = VALUES(`offerrewardtext_loc4`);
INSERT INTO `locales_quest` (`entry`, `offerrewardtext_loc4`) VALUES (8869, '你确定这是你想要的吗?成为打造战锤的铁匠?记住，你将永远都不能再打造刀剑和战斧了。$B$B') ON DUPLICATE KEY UPDATE `offerrewardtext_loc4` = VALUES(`offerrewardtext_loc4`);
